package alphametics

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle of the form "A + BB == ILL".
// It returns a map from each letter to the digit it represents,
// or an error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}

	words := strings.Split(eq[0], "+")
	words = append(words, eq[1])

	// Each word contributes its place values to the coefficient of
	// each letter, with the result word subtracted. A solution is
	// any assignment of distinct digits such that the weighted sum
	// of the coefficients is zero.
	coeff := make(map[rune]int)
	leading := make(map[rune]bool)
	for _, w := range words {
		w = strings.TrimSpace(w)
		if w == "" {
			return nil, fmt.Errorf("invalid puzzle %q: empty word", puzzle)
		}
		if len(w) > 1 {
			leading[rune(w[0])] = true
		}
		power := 1
		for i := len(w) - 1; i >= 0; i-- {
			c := rune(w[i])
			if !isLetter(c) {
				return nil, fmt.Errorf("invalid puzzle %q: %q is not a letter", puzzle, string(c))
			}
			coeff[c] += power
			power *= 10
		}
	}

	if len(coeff) > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	// Visit letters with the largest magnitude coefficients first so
	// the pruning bound below cuts the search space quickly.
	letters := make([]rune, 0, len(coeff))
	for l := range coeff {
		letters = append(letters, l)
	}
	sort.Slice(letters, func(i, j int) bool {
		return abs(coeff[letters[i]]) > abs(coeff[letters[j]])
	})

	// suffix[i] bounds the magnitude of the total contribution of
	// letters i..n-1, no matter which digits they receive.
	suffix := make([]int, len(letters)+1)
	for i := len(letters) - 1; i >= 0; i-- {
		suffix[i] = suffix[i+1] + 9*abs(coeff[letters[i]])
	}

	assign := make(map[rune]int)
	used := make([]bool, 10)
	var backtrack func(i int, sum int) bool
	backtrack = func(i int, sum int) bool {
		if abs(sum) > suffix[i] {
			return false
		}
		if i == len(letters) {
			return sum == 0
		}
		l := letters[i]
		for d := 0; d < 10; d++ {
			if used[d] {
				continue
			}
			if d == 0 && leading[l] {
				continue
			}
			used[d] = true
			assign[l] = d
			if backtrack(i+1, sum+coeff[l]*d) {
				return true
			}
			used[d] = false
		}
		delete(assign, l)
		return false
	}

	if !backtrack(0, 0) {
		return nil, errors.New("no solution")
	}

	result := make(map[string]int, len(assign))
	for l, d := range assign {
		result[string(l)] = d
	}
	return result, nil
}

func isLetter(c rune) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

